+func ParseAllCheckpointsFromFinalTrailerBlock(commitMessage string) []checkpointID.CheckpointID {
+	lines := finalTrailerBlock(commitMessage)
+	if len(lines) == 0 {
+		return nil
+	}
+
+	seen := make(map[string]bool)
