635	// inheritSquashedCheckpointTrailers handles a commit made while `git merge
636	// --squash` is in progress (SQUASH_MSG present): the squashed commits'
637	// Entire-Checkpoint trailers are carried into the message when a staged path is
638	// one the recorded commits changed. `commit -m` reports source "message", not "squash", so this runs
639	// before the source switch — but only for those two sources: an amend must
640	// keep its own logic even when an abandoned squash left SQUASH_MSG behind.
641	// Returns the inherited IDs; nil when there are none or the message is
642	// unusable. Ordinary matching runs afterwards either way.
643	func (s *ManualCommitStrategy) inheritSquashedCheckpointTrailers(ctx context.Context, commitMsgFile, source string) []id.CheckpointID {
644		if source != commitSourceMessage && source != "squash" {
645			return nil
646		}
647		logCtx := logging.WithComponent(ctx, "checkpoint")
648		gitDir, err := GetGitDir(ctx)
649		if err != nil {
650			return nil
651		}
652		// SQUASH_MSG lives in the PER-WORKTREE git dir, like the sequencer markers.
653		// The root is the shared registry handle (gitdir.OpenAt): never close it.
654		root, err := gitdir.OpenAt(gitDir)
655		if err != nil {
656			return nil
657		}
658		squashMsg, err := osroot.ReadFileNoFollow(root, "SQUASH_MSG")
659		if err != nil {
660			return nil // no squash in progress (or unreadable: fall through to normal matching)
661		}
662	
663		inherited := withoutDeletedCheckpoints(ctx, trailers.ParseAllCheckpoints(string(squashMsg)))
664		if len(inherited) == 0 {
665			return nil
666		}
667		repo, err := OpenRepository(ctx)
668		if err != nil {
669			return nil
670		}
671		defer repo.Close()
672		if !squashTouchesStagedPath(ctx, repo, squashMsg) {
673			stripInheritedCheckpointTrailers(commitMsgFile, inherited)
674			logging.Debug(logCtx, "prepare-commit-msg: ignored stale squash message whose commits changed none of the staged paths",
675				slog.String("source", source),
676				slog.Int("inherited", len(inherited)))
677			return nil
678		}
679		content, err := os.ReadFile(commitMsgFile) //nolint:gosec // commitMsgFile is provided by git hook
680		if err != nil {
681			return nil // nothing inherited; let ordinary matching report its own failure
682		}
683		message := string(content)
684		present := make(map[string]bool)
685		for _, cpID := range trailers.ParseAllCheckpoints(message) {
686			present[cpID.String()] = true
687		}
688		added := 0
689		for _, cpID := range inherited {
690			if present[cpID.String()] {
691				continue
692			}
693			message = addInheritedCheckpointTrailer(message, cpID, source)
694			added++
695		}
696		if added == 0 {
697			logging.Debug(logCtx, "prepare-commit-msg: squash in progress, message already carries the squashed trailers",
698				slog.String("source", source),
699				slog.Int("inherited", len(inherited)))
700			return inherited
701		}
702		if err := os.WriteFile(commitMsgFile, []byte(message), 0o600); err != nil { //nolint:gosec // path from git hook arg
703			return nil // nothing landed; hooks stay silent, ordinary matching may still try
704		}
705		logging.Info(logCtx, "prepare-commit-msg: inherited checkpoint trailers from the squashed commits",
706			slog.String("strategy", "manual-commit"),
707			slog.String("source", source),
708			slog.Int("inherited", len(inherited)),
709			slog.Int("added", added))
710		return inherited
711	}
