package integration

import (
	"os"
	"os/exec"
	"path/filepath"
	"strings"
	"testing"

	"github.com/stretchr/testify/require"

	"github.com/entireio/cli/cmd/entire/cli/trailers"
)

// Scratch (not committed): real `git commit` runs Entire's hooks and does its
// own cleanup, with the repository's comment prefix.
func TestScratchRealGitCommit(t *testing.T) {
	cases := []struct {
		name, commentChar, template string
		amend                       bool
	}{
		{name: "default", commentChar: ""},
		{name: "semicolon", commentChar: ";"},
		{name: "commentString", commentChar: "//"},
		{name: "auto-with-hash-template", commentChar: "auto", template: "# Release notes\n"},
		{name: "semicolon-amend", commentChar: ";", amend: true},
		{name: "auto-amend", commentChar: "auto", amend: true},
	}
	for _, tc := range cases {
		t.Run(tc.name, func(t *testing.T) {
			env := NewFeatureBranchEnv(t)
			if tc.commentChar != "" {
				setRepoGitConfig(env, "core.commentChar", tc.commentChar)
			}
			hooks := t.TempDir()
			for _, h := range []string{"prepare-commit-msg", "post-commit"} {
				script := "#!/bin/sh\nexec \"" + getTestBinary() + "\" hooks git " + h + " \"$@\"\n"
				require.NoError(t, os.WriteFile(filepath.Join(hooks, h), []byte(script), 0o755))
			}
			gitCommit := func(args ...string) {
				full := append([]string{"-c", "core.hooksPath=" + hooks, "commit"}, args...)
				cmd := exec.CommandContext(t.Context(), "git", full...)
				cmd.Dir = env.RepoDir
				cmd.Env = append(env.gitHookEnv(), "GIT_EDITOR="+os.Getenv("SCRATCH_EDITOR"))
				out, err := cmd.CombinedOutput()
				require.NoError(t, err, "%s", out)
			}

			authorityAgentTurn(env, "mine.txt", "my agent work\n")
			env.GitAdd("mine.txt")
			args := []string{}
			if tc.template != "" {
				tmpl := filepath.Join(t.TempDir(), "tmpl")
				require.NoError(t, os.WriteFile(tmpl, []byte(tc.template), 0o644))
				args = append(args, "-t", tmpl)
			}
			if tc.amend {
				gitCommit("-m", "My change\n\n#42 is the issue")
				authorityAgentTurn(env, "more.txt", "more\n")
				env.GitAdd("more.txt")
				args = append(args, "--amend")
			}
			gitCommit(args...)

			msg := env.GetCommitMessage(env.GetHeadHash())
			t.Logf("recorded message:\n%s", msg)
			require.NotContains(t, msg, "Remove the Entire-Checkpoint trailer above")
			ids := trailers.ParseAllCheckpoints(msg)
			require.Len(t, ids, 1, "exactly one trailer: %q", msg)
			final, ok := trailers.ParseCheckpointFromFinalTrailerBlock(msg)
			require.True(t, ok, "%q", msg)
			require.True(t, advCheckpointStored(env, final.String()), "post-commit condensed into %s", final)
			_ = strings.TrimSpace
		})
	}
}
EOF
